#!/usr/bin/env node
// Generated by GetMCP. A small MCP server (stdio) that exposes the curated
// tools in tools.json and forwards each call to your HTTP API.
//
//   API_AUTH_HEADER   value for the Authorization header, e.g. "Bearer sk_..."
//   API_HEADERS       extra headers as JSON, e.g. '{"X-Api-Version":"2024-01-01"}'
//   API_BASE_URL      override the base URL from the spec
//   GETMCP_READ_ONLY  set to 1 to refuse every tool that is not a plain read
//   GETMCP_MAX_CHARS  cap on response text handed back to the agent (default 20000)

import { Server } from '@modelcontextprotocol/sdk/server/index.js';
import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';
import { CallToolRequestSchema, ListToolsRequestSchema } from '@modelcontextprotocol/sdk/types.js';
import { readFileSync } from 'node:fs';

const manifest = JSON.parse(readFileSync(new URL('./tools.json', import.meta.url), 'utf8'));

const BASE_URL = (process.env.API_BASE_URL ?? manifest.baseUrl ?? '').replace(/\/+$/, '');
if (!BASE_URL) {
  console.error('No base URL: the spec did not declare one. Set API_BASE_URL.');
  process.exit(1);
}
const READ_ONLY = /^(1|true|yes)$/i.test(process.env.GETMCP_READ_ONLY ?? '');
const MAX_CHARS = Number(process.env.GETMCP_MAX_CHARS) || 20_000;

let extraHeaders = {};
if (process.env.API_HEADERS) {
  try {
    extraHeaders = JSON.parse(process.env.API_HEADERS);
  } catch {
    console.error('API_HEADERS is not valid JSON; ignoring it.');
  }
}

const tools = new Map(manifest.tools.map((t) => [t.name, t]));

/** Flatten nested values the way form / deepObject encoding expects: a[b][0]=c */
function flatten(prefix, value, out) {
  if (value === undefined || value === null) return;
  if (Array.isArray(value)) value.forEach((v, i) => flatten(`${prefix}[${i}]`, v, out));
  else if (typeof value === 'object') for (const [k, v] of Object.entries(value)) flatten(`${prefix}[${k}]`, v, out);
  else out.push([prefix, String(value)]);
}

function buildRequest(route, args) {
  let path = route.path;
  const query = new URLSearchParams();

  for (const p of route.params) {
    const value = args[p.arg];
    if (p.in === 'path') {
      if (value === undefined || value === null || value === '') throw new Error(`missing required argument "${p.arg}"`);
      path = path.replace(`{${p.name}}`, encodeURIComponent(String(value)));
      continue;
    }
    if (value === undefined || value === null) continue;
    if (p.style === 'deepObject' && typeof value === 'object') {
      const pairs = [];
      flatten(p.name, value, pairs);
      for (const [k, v] of pairs) query.append(k, v);
    } else if (Array.isArray(value)) {
      for (const v of value) query.append(p.name, typeof v === 'object' ? JSON.stringify(v) : String(v));
    } else {
      query.append(p.name, typeof value === 'object' ? JSON.stringify(value) : String(value));
    }
  }

  const headers = { Accept: 'application/json', 'User-Agent': 'getmcp-server', ...extraHeaders };
  if (process.env.API_AUTH_HEADER) headers.Authorization = process.env.API_AUTH_HEADER;

  let body;
  if (route.body && args[route.body.arg] !== undefined) {
    const payload = args[route.body.arg];
    if (route.body.encoding === 'form') {
      const pairs = [];
      for (const [k, v] of Object.entries(payload ?? {})) flatten(k, v, pairs);
      body = new URLSearchParams(pairs).toString();
      headers['Content-Type'] = 'application/x-www-form-urlencoded';
    } else {
      body = JSON.stringify(payload);
      headers['Content-Type'] = 'application/json';
    }
  }

  const qs = query.toString();
  return { url: BASE_URL + path + (qs ? `?${qs}` : ''), init: { method: route.method, headers, body } };
}

const server = new Server({ name: manifest.name, version: manifest.version ?? '0.0.1' }, { capabilities: { tools: {} } });

server.setRequestHandler(ListToolsRequestSchema, async () => ({
  tools: manifest.tools
    .filter((t) => !READ_ONLY || t.annotations?.readOnlyHint)
    .map(({ name, description, inputSchema, annotations }) => ({ name, description, inputSchema, annotations })),
}));

server.setRequestHandler(CallToolRequestSchema, async (request) => {
  const tool = tools.get(request.params.name);
  const fail = (text) => ({ content: [{ type: 'text', text }], isError: true });
  if (!tool) return fail(`Unknown tool: ${request.params.name}`);
  if (READ_ONLY && !tool.annotations?.readOnlyHint) {
    return fail(`Refused: ${tool.name} is a write and this server is running with GETMCP_READ_ONLY.`);
  }

  try {
    const { url, init } = buildRequest(tool.route, request.params.arguments ?? {});
    const res = await fetch(url, { ...init, signal: AbortSignal.timeout(30_000) });
    let text = await res.text();
    if (text.length > MAX_CHARS) {
      text = `${text.slice(0, MAX_CHARS)}\n… [truncated ${text.length - MAX_CHARS} characters; narrow the request]`;
    }
    return { content: [{ type: 'text', text: `HTTP ${res.status}\n${text}` }], isError: !res.ok };
  } catch (err) {
    const cause = err?.cause?.message ? ` (${err.cause.message})` : '';
    return fail(`Request failed: ${err?.message ?? err}${cause}`);
  }
});

await server.connect(new StdioServerTransport());
console.error(`${manifest.name}: ${manifest.tools.length} tools → ${BASE_URL}${READ_ONLY ? ' (read-only)' : ''}`);
